<?php
require_once __DIR__ . '/../includes/functions.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $id = (int) ($_POST['id_order'] ?? 0); $status = $_POST['status'] ?? '';
    $allowed = ['Menunggu Konfirmasi','Diproses','Dikirim','Selesai','Dibatalkan'];
    if (!in_array($status, $allowed, true)) set_flash('danger', 'Status pesanan tidak valid.');
    else { $stmt = $pdo->prepare('UPDATE orders SET status=? WHERE id_order=?'); $stmt->execute([$status, $id]); set_flash('success', 'Status pesanan diperbarui.'); }
    redirect('admin/order.php?detail=' . $id);
}
$detailId = (int) ($_GET['detail'] ?? 0);
if ($detailId) {
    $stmt = $pdo->prepare('SELECT o.*,u.nama,u.email,u.alamat,u.nomor_telepon FROM orders o JOIN `user` u ON u.id_user=o.id_user WHERE o.id_order=?'); $stmt->execute([$detailId]); $order = $stmt->fetch();
    if (!$order) { set_flash('danger', 'Pesanan tidak ditemukan.'); redirect('admin/order.php'); }
    $stmt = $pdo->prepare('SELECT od.*,b.judul_buku FROM order_detail od JOIN buku b ON b.id_buku=od.id_buku WHERE od.id_order=?'); $stmt->execute([$detailId]); $details = $stmt->fetchAll(); $buyer = $order;
    $page_title = 'Detail Pesanan'; require __DIR__ . '/../includes/admin_header.php';
    ?>
    <div class="admin-order-detail"><section class="card"><div class="section-heading"><div><p>Invoice #BBS-<?= str_pad((string)$order['id_order'],5,'0',STR_PAD_LEFT) ?></p><h2>Informasi Pesanan</h2></div><span class="badge badge-<?= order_status_class($order['status']) ?>"><?= e($order['status']) ?></span></div><div class="book-meta"><span>Pembeli</span><b><?= e($order['nama']) ?></b><span>Email</span><b><?= e($order['email']) ?></b><span>Telepon</span><b><?= e($order['nomor_telepon']) ?></b><span>Alamat</span><b><?= nl2br(e($order['alamat'])) ?></b><span>Pembayaran</span><b><?= e($order['metode_pembayaran']) ?></b></div><?php if ($order['bukti_pembayaran']): ?><div class="form-group"><label>Bukti pembayaran transfer</label><?php if (str_ends_with($order['bukti_pembayaran'], '.pdf')): ?><a class="button button-outline" target="_blank" href="<?= url($order['bukti_pembayaran']) ?>">Buka PDF bukti pembayaran</a><?php else: ?><a target="_blank" href="<?= url($order['bukti_pembayaran']) ?>"><img class="image-preview" src="<?= url($order['bukti_pembayaran']) ?>" alt="Bukti pembayaran"></a><?php endif; ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id_order" value="<?= $order['id_order'] ?>"><div class="form-group"><label for="status">Status pesanan</label><select id="status" name="status"><?php foreach (['Menunggu Konfirmasi','Diproses','Dikirim','Selesai','Dibatalkan'] as $status): ?><option <?= $status === $order['status'] ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></div><button type="submit">Simpan Status</button><a class="button button-outline" href="<?= url('admin/order.php') ?>">Kembali</a></form></section><section><?php require __DIR__ . '/../includes/receipt.php'; ?><div class="receipt-actions"><button onclick="window.print()">🖨 Cetak Struk</button></div></section></div>
    <?php require __DIR__ . '/../includes/admin_footer.php'; exit;
}
$statusFilter = trim($_GET['status'] ?? ''); $allowed = ['Menunggu Konfirmasi','Diproses','Dikirim','Selesai','Dibatalkan']; $params=[]; $where=''; if (in_array($statusFilter,$allowed,true)) { $where=' WHERE o.status=?'; $params[]=$statusFilter; }
$stmt = $pdo->prepare('SELECT o.*,u.nama,u.email FROM orders o JOIN `user` u ON u.id_user=o.id_user' . $where . ' ORDER BY o.tanggal_order DESC'); $stmt->execute($params); $orders=$stmt->fetchAll(); $page_title='Manajemen Pesanan'; require __DIR__ . '/../includes/admin_header.php';
?>
<div class="admin-toolbar"><p class="helper">Tinjau detail pesanan, bukti pembayaran, dan ubah status proses.</p><form class="search-inline" method="get"><select name="status" data-auto-submit><option value="">Semua status</option><?php foreach ($allowed as $status): ?><option value="<?= e($status) ?>" <?= $statusFilter===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></form></div><section class="card table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Pembeli</th><th>Tanggal</th><th>Metode</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php if($orders): ?><?php foreach($orders as $order): ?><tr><td>#BBS-<?= str_pad((string)$order['id_order'],5,'0',STR_PAD_LEFT) ?></td><td><b><?= e($order['nama']) ?></b><br><span class="helper"><?= e($order['email']) ?></span></td><td><?= date('d M Y H:i',strtotime($order['tanggal_order'])) ?></td><td><?= e($order['metode_pembayaran']) ?></td><td><?= rupiah($order['total_harga']) ?></td><td><span class="badge badge-<?= order_status_class($order['status']) ?>"><?= e($order['status']) ?></span></td><td><a class="button button-small" href="<?= url('admin/order.php?detail='.$order['id_order']) ?>">Detail</a></td></tr><?php endforeach; ?><?php else: ?><tr><td colspan="7" class="helper">Belum ada pesanan.</td></tr><?php endif; ?></tbody></table></section>
